window.OPUS_PAGES = window.OPUS_PAGES || {};
window.OPUS_PAGES["049"] = "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Riso Lab — Halftone Print Studio</title>\n<meta name=\"description\" content=\"A risograph print simulator: procedural artwork is separated into two or three spot inks and screened as halftone dots at classic angles, overprinted with multiply blending, misregistration and ink grain on off-white paper.\">\n<meta name=\"theme-color\" content=\"#ffffff\">\n<style>\n:root{\n  --ink:#0b0b0b;\n  --paper:#f4efe2;\n  --wall:#e8e6e0;\n  --pink:#ff48b0;\n  --blue:#0078bf;\n  --yellow:#ffe800;\n  --hair:1px solid #0b0b0b;\n  --sans:\"Helvetica Neue\",Helvetica,Arial,\"Nimbus Sans\",\"Liberation Sans\",sans-serif;\n  --mono:\"SF Mono\",Menlo,Consolas,\"DejaVu Sans Mono\",\"Liberation Mono\",monospace;\n  --panel:372px;\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;height:100%}\nbody{background:var(--wall);color:var(--ink);font-family:var(--sans);-webkit-font-smoothing:antialiased}\n.app{display:grid;grid-template-columns:var(--panel) 1fr;height:100vh;height:100dvh}\n\n/* ---------------- panel ---------------- */\n.panel{background:#fff;border-right:var(--hair);overflow-y:auto;overflow-x:hidden;scrollbar-width:thin;scrollbar-color:#0b0b0b #fff}\n.brand{padding:22px 22px 16px;border-bottom:var(--hair);position:relative}\n.wordmark{position:relative;display:inline-block;margin:0;font-size:44px;line-height:.9;font-weight:900;letter-spacing:-.035em;font-family:\"Helvetica Neue\",Helvetica,\"Arial Black\",Arial,sans-serif}\n.wordmark .k{position:relative;color:var(--ink);mix-blend-mode:multiply}\n.wordmark .p{position:absolute;left:3px;top:2px;color:var(--pink);mix-blend-mode:multiply;white-space:nowrap}\n.wordmark .b{position:absolute;left:-2px;top:-1px;color:var(--blue);mix-blend-mode:multiply;white-space:nowrap;opacity:.9}\n.brand .meta{display:flex;justify-content:space-between;margin-top:12px;font:10px/1.3 var(--mono);letter-spacing:.08em;text-transform:uppercase}\n.brand .meta span:last-child{text-align:right}\n.sec{border-bottom:var(--hair);padding:14px 22px 18px}\n.sec h2{display:flex;justify-content:space-between;align-items:baseline;margin:0 0 12px;font:700 10px/1 var(--mono);letter-spacing:.14em;text-transform:uppercase}\n.sec h2 .n{font-weight:400;opacity:.55}\n.lbl{display:flex;justify-content:space-between;align-items:baseline;font:10px/1 var(--mono);letter-spacing:.1em;text-transform:uppercase;margin:12px 0 7px}\n.lbl output{font-variant-numeric:tabular-nums;letter-spacing:.04em}\n\n/* sources */\n.sources{display:grid;grid-template-columns:repeat(5,1fr);border:var(--hair)}\n.src{appearance:none;border:0;border-right:var(--hair);background:#fff;color:var(--ink);cursor:pointer;padding:9px 0 7px;display:flex;flex-direction:column;align-items:center;gap:5px;font:9.5px/1 var(--mono);letter-spacing:.06em;text-transform:uppercase;transition:background .15s,color .15s}\n.src:last-child{border-right:0}\n.src svg{width:26px;height:26px}\n.src:hover{background:#f3f3f1}\n.src[aria-pressed=\"true\"]{background:var(--ink);color:#fff}\n.src-extra{margin-top:12px;display:grid;grid-template-columns:96px 1fr;gap:12px;align-items:start}\n.thumb{width:96px;height:120px;border:var(--hair);display:block;background:#fff}\n.src-note{font:10.5px/1.5 var(--mono);color:#333;margin:0}\n.src-note b{font-weight:700}\n.word-in{width:100%;font:900 22px/1 var(--sans);letter-spacing:-.02em;text-transform:uppercase;border:0;border-bottom:2px solid var(--ink);padding:4px 0 6px;background:transparent;color:var(--ink);border-radius:0}\n.word-in:focus{outline:none;border-bottom-color:var(--pink)}\n.pad-wrap{position:relative}\n#pad{width:100%;aspect-ratio:4/5;border:var(--hair);display:block;touch-action:none;cursor:crosshair;background:#fbfaf6}\n.brushes{display:flex;gap:6px;margin-top:8px;align-items:center;flex-wrap:wrap}\n.brush{appearance:none;width:22px;height:22px;border-radius:50%;border:1px solid var(--ink);cursor:pointer;padding:0;position:relative}\n.brush[aria-pressed=\"true\"]::after{content:\"\";position:absolute;inset:-5px;border:1.5px solid var(--ink);border-radius:50%}\n.mini{appearance:none;border:var(--hair);background:#fff;font:9.5px/1 var(--mono);letter-spacing:.08em;text-transform:uppercase;padding:6px 8px;cursor:pointer;margin-left:auto}\n.mini:hover{background:var(--ink);color:#fff}\n[hidden]{display:none!important}\n\n/* drums */\n.drum-row{display:grid;grid-template-columns:auto 1fr 44px;gap:12px;align-items:center;padding:12px 0;border-top:1px dashed rgba(11,11,11,.35)}\n.drum-row:first-of-type{border-top:0;padding-top:2px}\n.drum{appearance:none;border:0;background:none;padding:0;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:6px;font:9px/1 var(--mono);letter-spacing:.1em;text-transform:uppercase;color:var(--ink)}\n.slot{position:relative;width:86px;height:38px;border-radius:6px;background:linear-gradient(180deg,#1b1b1b,#3a3a3a 50%,#111);box-shadow:inset 0 2px 5px rgba(0,0,0,.8);overflow:hidden}\n.cyl{position:absolute;left:10px;right:10px;top:6px;bottom:6px;border-radius:3px;\n  background:\n    linear-gradient(180deg,rgba(255,255,255,.62) 0%,rgba(255,255,255,.12) 30%,rgba(255,255,255,0) 45%,rgba(0,0,0,.14) 70%,rgba(0,0,0,.42) 100%),\n    repeating-linear-gradient(180deg,rgba(0,0,0,0) 0 3px,rgba(0,0,0,.16) 3px 4px),\n    var(--c,#ff48b0);\n  background-size:100% 100%,100% 26px,100% 100%;\n  transition:transform .55s cubic-bezier(.3,1.4,.5,1),filter .4s,opacity .4s}\n.cyl::before,.cyl::after{content:\"\";position:absolute;top:-3px;bottom:-3px;width:9px;border-radius:50%;background:radial-gradient(circle at 40% 40%,#9a9a9a,#3a3a3a 60%,#1a1a1a)}\n.cyl::before{left:-7px}\n.cyl::after{right:-7px}\n.drum.spin .cyl{animation:roll .9s cubic-bezier(.15,.7,.3,1)}\n@keyframes roll{from{background-position:0 0,0 0,0 0}to{background-position:0 0,0 104px,0 0}}\n.drum[aria-pressed=\"false\"] .cyl{transform:translateX(-62%);filter:grayscale(.85) brightness(.9);opacity:.55}\n.drum .state{display:flex;align-items:center;gap:5px}\n.led{width:7px;height:7px;border-radius:50%;background:#bbb;box-shadow:inset 0 1px 1px rgba(0,0,0,.4);transition:background .3s,box-shadow .3s}\n.drum[aria-pressed=\"true\"] .led{background:#27d06b;box-shadow:0 0 6px #27d06b}\n.drum:focus-visible{outline:2px solid var(--pink);outline-offset:3px}\n.drum-ctl{min-width:0}\n.inks{display:flex;gap:5px;flex-wrap:wrap}\n.inks label{position:relative;cursor:pointer}\n.inks input{position:absolute;opacity:0;width:1px;height:1px}\n.inks .sw{display:block;width:20px;height:20px;border:1px solid var(--ink);transition:transform .15s}\n.inks input:checked + .sw{transform:scale(1.12);box-shadow:0 0 0 2px #fff,0 0 0 3.5px var(--ink)}\n.inks input:focus-visible + .sw{box-shadow:0 0 0 2px #fff,0 0 0 4px var(--pink)}\n.ink-name{font:10px/1 var(--mono);letter-spacing:.08em;text-transform:uppercase;margin:0 0 7px;display:flex;justify-content:space-between}\n.plate{width:44px;height:55px;border:var(--hair);display:block;background:#fff}\n\n/* ranges */\ninput[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:18px;background:transparent;margin:0;cursor:pointer}\ninput[type=range]::-webkit-slider-runnable-track{height:1px;background:var(--ink)}\ninput[type=range]::-moz-range-track{height:1px;background:var(--ink)}\ninput[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:12px;height:12px;margin-top:-5.5px;background:var(--ink);border:0;border-radius:0;transition:transform .12s}\ninput[type=range]::-moz-range-thumb{width:12px;height:12px;background:var(--ink);border:0;border-radius:0}\ninput[type=range]:hover::-webkit-slider-thumb{transform:scale(1.25)}\ninput[type=range]:focus-visible{outline:none}\ninput[type=range]:focus-visible::-webkit-slider-thumb{background:var(--pink);box-shadow:0 0 0 3px rgba(255,72,176,.3)}\ninput[type=range]:focus-visible::-moz-range-thumb{background:var(--pink)}\n.angle{margin-top:8px}\n\n.seg{display:grid;grid-template-columns:repeat(3,1fr);border:var(--hair)}\n.seg button{appearance:none;border:0;border-right:var(--hair);background:#fff;padding:8px 4px;display:flex;align-items:center;justify-content:center;gap:6px;cursor:pointer;font:10px/1 var(--mono);letter-spacing:.08em;text-transform:uppercase;color:var(--ink)}\n.seg button:last-child{border-right:0}\n.seg button svg{width:14px;height:14px}\n.seg button[aria-pressed=\"true\"]{background:var(--ink);color:#fff}\n.src:focus-visible,.seg button:focus-visible,.btn:focus-visible,.mini:focus-visible,.brush:focus-visible{outline:2px solid var(--pink);outline-offset:2px;position:relative;z-index:1}\n.actions{display:grid;grid-template-columns:1fr 1fr;gap:10px}\n.btn{appearance:none;border:var(--hair);background:#fff;color:var(--ink);padding:13px 10px;font:700 11px/1 var(--mono);letter-spacing:.1em;text-transform:uppercase;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:8px;transition:background .15s,color .15s,transform .1s}\n.btn svg{width:14px;height:14px}\n.btn:hover{background:#f1f0ec}\n.btn:active{transform:translateY(1px)}\n.btn.dark{background:var(--ink);color:#fff}\n.btn.dark:hover{background:#262626}\n.foot{padding:14px 22px 22px;font:10px/1.6 var(--mono);color:#444}\n.foot p{margin:0 0 6px}\n\n/* ---------------- wall + poster ---------------- */\n.wall{position:relative;overflow:hidden;display:flex;flex-direction:column;align-items:center;justify-content:center;padding:40px 30px;\n  background:\n    radial-gradient(120% 90% at 30% 0%,rgba(255,255,255,.75),rgba(255,255,255,0) 60%),\n    radial-gradient(90% 70% at 100% 100%,rgba(120,110,95,.18),rgba(120,110,95,0) 70%),\n    var(--wall)}\n.wall::before{content:\"\";position:absolute;inset:0;pointer-events:none;opacity:.5;\n  background-image:radial-gradient(rgba(0,0,0,.05) 1px,transparent 1.3px),radial-gradient(rgba(255,255,255,.5) 1px,transparent 1.3px);\n  background-size:7px 9px,11px 13px;background-position:0 0,3px 5px}\n.wall-note{position:absolute;left:26px;top:22px;font:10px/1.55 var(--mono);letter-spacing:.08em;text-transform:uppercase;color:#6d6a63}\n.wall-note b{color:var(--ink);font-weight:700}\n.wall-ruler{position:absolute;right:24px;top:22px;bottom:22px;width:18px;border-left:1px solid rgba(11,11,11,.35);\n  background:repeating-linear-gradient(180deg,rgba(11,11,11,.45) 0 1px,transparent 1px 10px) left top/6px 100% no-repeat,\n             repeating-linear-gradient(180deg,rgba(11,11,11,.55) 0 1px,transparent 1px 50px) left top/11px 100% no-repeat;opacity:.55}\n.poster-wrap{position:relative;transform:rotate(-.8deg);transition:transform .6s cubic-bezier(.3,1.3,.5,1)}\n.poster-wrap:hover{transform:rotate(-.5deg) translateY(-2px)}\n.poster{position:relative;background:var(--paper);box-shadow:0 1px 1px rgba(0,0,0,.12),0 12px 22px -8px rgba(40,30,20,.35),0 34px 60px -30px rgba(40,30,20,.55)}\n.poster::after{content:\"\";position:absolute;inset:0;pointer-events:none;\n  background:linear-gradient(115deg,rgba(255,255,255,.22),rgba(255,255,255,0) 35%),linear-gradient(0deg,rgba(90,70,40,.06),rgba(90,70,40,0) 12%),\n  radial-gradient(60% 30% at 100% 100%,rgba(60,45,25,.1),rgba(60,45,25,0))}\n.poster canvas{position:absolute;left:0;top:0;width:100%;height:100%;display:block}\n.poster .ink{mix-blend-mode:multiply;transition:opacity .35s ease,transform .5s cubic-bezier(.3,1.25,.5,1)}\n.poster .ink.off{opacity:0}\n.poster .ink.wipe{animation:wipe .62s cubic-bezier(.45,0,.2,1) both}\n@keyframes wipe{from{clip-path:inset(0 0 100% 0)}to{clip-path:inset(0 0 0 0)}}\n#grain{mix-blend-mode:multiply;opacity:.8}\n#tooth{mix-blend-mode:screen;opacity:.9}\n.tape{position:absolute;z-index:3;width:118px;height:32px;top:-15px;\n  background:linear-gradient(180deg,rgba(255,255,255,.35),rgba(255,255,255,0) 40%,rgba(120,105,70,.12)),repeating-linear-gradient(90deg,rgba(255,255,255,.14) 0 2px,rgba(255,255,255,0) 2px 5px),rgba(214,204,168,.68);\n  filter:drop-shadow(0 1px 1.5px rgba(60,45,20,.28));\n  clip-path:polygon(2% 8%,6% 0,11% 9%,16% 1%,21% 7%,100% 3%,97% 14%,100% 26%,96% 38%,99% 52%,95% 66%,100% 79%,97% 92%,99% 100%,0 96%,3% 84%,0 70%,4% 57%,0 44%,3% 31%,0 18%)}\n.tape.l{left:-34px;transform:rotate(-38deg)}\n.tape.r{right:-34px;transform:rotate(36deg)}\n.caption{margin-top:26px;display:flex;gap:18px;align-items:flex-start;max-width:640px;width:100%;font:10.5px/1.6 var(--mono);color:#2b2a27;position:relative}\n.caption .no{font:900 30px/1 var(--sans);letter-spacing:-.03em}\n.caption p{margin:0}\n.caption .t{font-weight:700;letter-spacing:.08em;text-transform:uppercase}\n.caption > div:not(.cap-actions){flex:1 1 0;min-width:0}\n.cap-actions{display:flex;flex-direction:column;gap:8px;margin-left:auto;flex:none}\n.cap-actions .btn{padding:11px 14px;min-width:152px;justify-content:flex-start}\n.busy{position:absolute;left:0;top:-18px;font:10px/1 var(--mono);letter-spacing:.1em;text-transform:uppercase;opacity:0;transition:opacity .2s}\n.busy.on{opacity:.7}\n.toast{position:fixed;z-index:20;left:50%;bottom:24px;transform:translate(-50%,12px);background:var(--ink);color:#fff;font:11px/1 var(--mono);letter-spacing:.08em;text-transform:uppercase;padding:12px 16px;opacity:0;transition:opacity .25s,transform .25s;pointer-events:none}\n.toast.show{opacity:1;transform:translate(-50%,0)}\n\n@media (max-width:900px){\n  html,body{height:auto}\n  .app{display:flex;flex-direction:column-reverse;height:auto}\n  .panel{overflow:visible;border-right:0;border-top:var(--hair)}\n  .wall{padding:86px 16px 30px;min-height:0}\n  .caption{flex-wrap:wrap}\n  .cap-actions{width:100%;flex-direction:row;margin-left:0}\n  .cap-actions .btn{flex:1}\n  .wall-ruler{display:none}\n  .wall-note{left:16px;top:16px}\n  .caption{margin-top:20px;gap:12px}\n  .caption .no{font-size:24px}\n  .brand{padding:18px 16px 14px}\n  .sec{padding:14px 16px 16px}\n  .foot{padding:14px 16px 20px}\n  .tape{width:92px;height:26px;top:-12px}\n  .tape.l{left:-24px}.tape.r{right:-24px}\n}\n@media (prefers-reduced-motion:reduce){\n  .poster .ink.wipe{animation:none}\n  .drum.spin .cyl{animation:none}\n  .cyl,.poster .ink,.poster-wrap{transition:none}\n}\n</style>\n</head>\n<body>\n<div class=\"app\">\n  <aside class=\"panel\" aria-label=\"Print studio controls\">\n    <header class=\"brand\">\n      <h1 class=\"wordmark\" aria-label=\"Riso Lab\"><span class=\"b\" aria-hidden=\"true\">RISO LAB</span><span class=\"p\" aria-hidden=\"true\">RISO LAB</span><span class=\"k\" aria-hidden=\"true\">RISO LAB</span></h1>\n      <div class=\"meta\"><span>Halftone print studio<br>stencil-duplicator sim.</span><span>Paper F4EFE2<br>Multiply · 2–3 drums</span></div>\n    </header>\n\n    <section class=\"sec\" aria-labelledby=\"h-src\">\n      <h2 id=\"h-src\"><span>Source image</span><span class=\"n\">01</span></h2>\n      <div class=\"sources\" role=\"group\" aria-label=\"Choose the artwork to print\">\n        <button type=\"button\" class=\"src\" data-src=\"sphere\" aria-pressed=\"false\"><svg viewBox=\"0 0 26 26\" aria-hidden=\"true\"><circle cx=\"13\" cy=\"13\" r=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"/><circle cx=\"9.5\" cy=\"9.5\" r=\"3\" fill=\"currentColor\"/><path d=\"M5 20c4 3 12 3 16 0\" stroke=\"currentColor\" fill=\"none\"/></svg>Sphere</button>\n        <button type=\"button\" class=\"src\" data-src=\"sunset\" aria-pressed=\"true\"><svg viewBox=\"0 0 26 26\" aria-hidden=\"true\"><path d=\"M5 15a8 8 0 0116 0z\" fill=\"currentColor\"/><path d=\"M2 18h22M5 21h16M9 24h8\" stroke=\"currentColor\" stroke-width=\"1.4\"/></svg>Sunset</button>\n        <button type=\"button\" class=\"src\" data-src=\"word\" aria-pressed=\"false\"><svg viewBox=\"0 0 26 26\" aria-hidden=\"true\"><path d=\"M3 21L9 5h2l6 16M5.5 15h9\" stroke=\"currentColor\" stroke-width=\"1.8\" fill=\"none\"/><path d=\"M18 11v10M18 14a3 3 0 106 0 3 3 0 10-6 0\" stroke=\"currentColor\" stroke-width=\"1.6\" fill=\"none\"/></svg>Word</button>\n        <button type=\"button\" class=\"src\" data-src=\"face\" aria-pressed=\"false\"><svg viewBox=\"0 0 26 26\" aria-hidden=\"true\"><circle cx=\"13\" cy=\"13\" r=\"10\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.4\"/><path d=\"M7 11a3 3 0 016 0zM13 11a3 3 0 016 0z\" fill=\"currentColor\"/><path d=\"M13 12l-2 5h4z\" fill=\"currentColor\"/><rect x=\"9\" y=\"18.5\" width=\"8\" height=\"2\" fill=\"currentColor\"/></svg>Face</button>\n        <button type=\"button\" class=\"src\" data-src=\"doodle\" aria-pressed=\"false\"><svg viewBox=\"0 0 26 26\" aria-hidden=\"true\"><path d=\"M3 18c3-8 6-8 7 0s5 6 7-2 4-10 6-6\" stroke=\"currentColor\" stroke-width=\"1.8\" fill=\"none\" stroke-linecap=\"round\"/></svg>Doodle</button>\n      </div>\n      <div class=\"src-extra\">\n        <canvas class=\"thumb\" id=\"thumb\" width=\"192\" height=\"240\" role=\"img\" aria-label=\"The original full-colour artwork\"></canvas>\n        <div>\n          <p class=\"src-note\" id=\"srcNote\"><b>Sunset.</b> Layered ridges, a low sun and its broken reflection. The original, before separation.</p>\n          <div id=\"wordBox\" hidden>\n            <label class=\"lbl\" for=\"word\"><span>Your word</span><output id=\"wordLen\">4/10</output></label>\n            <input id=\"word\" class=\"word-in\" type=\"text\" maxlength=\"10\" value=\"RISO\" autocomplete=\"off\" spellcheck=\"false\">\n          </div>\n        </div>\n      </div>\n      <div id=\"padBox\" class=\"pad-wrap\" hidden>\n        <p class=\"lbl\"><span>Doodle pad — draw here</span><span id=\"padHint\">4 brushes</span></p>\n        <canvas id=\"pad\" width=\"480\" height=\"600\" aria-label=\"Doodle pad: draw with mouse, pen or finger\"></canvas>\n        <div class=\"brushes\" role=\"group\" aria-label=\"Brush colour\">\n          <button type=\"button\" class=\"brush\" data-c=\"#ff3fa4\" style=\"background:#ff3fa4\" aria-label=\"Pink brush\" aria-pressed=\"true\"></button>\n          <button type=\"button\" class=\"brush\" data-c=\"#1a6fd0\" style=\"background:#1a6fd0\" aria-label=\"Blue brush\" aria-pressed=\"false\"></button>\n          <button type=\"button\" class=\"brush\" data-c=\"#ffd400\" style=\"background:#ffd400\" aria-label=\"Yellow brush\" aria-pressed=\"false\"></button>\n          <button type=\"button\" class=\"brush\" data-c=\"#141414\" style=\"background:#141414\" aria-label=\"Black brush\" aria-pressed=\"false\"></button>\n          <button type=\"button\" class=\"mini\" id=\"padClear\">Clear pad</button>\n        </div>\n      </div>\n    </section>\n\n    <section class=\"sec\" aria-labelledby=\"h-drums\">\n      <h2 id=\"h-drums\"><span>Ink drums</span><span class=\"n\">02</span></h2>\n      <div id=\"drums\"></div>\n    </section>\n\n    <section class=\"sec\" aria-labelledby=\"h-screen\">\n      <h2 id=\"h-screen\"><span>Screen</span><span class=\"n\">03</span></h2>\n      <p class=\"lbl\" id=\"shapeLbl\"><span>Dot shape</span><span></span></p>\n      <div class=\"seg\" role=\"group\" aria-labelledby=\"shapeLbl\">\n        <button type=\"button\" data-shape=\"circle\" aria-pressed=\"true\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><circle cx=\"3.5\" cy=\"3.5\" r=\"2.4\" fill=\"currentColor\"/><circle cx=\"10.5\" cy=\"3.5\" r=\"1.6\" fill=\"currentColor\"/><circle cx=\"3.5\" cy=\"10.5\" r=\"1.2\" fill=\"currentColor\"/><circle cx=\"10.5\" cy=\"10.5\" r=\"2.8\" fill=\"currentColor\"/></svg>Circle</button>\n        <button type=\"button\" data-shape=\"line\" aria-pressed=\"false\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M0 2.5h14M0 7h14M0 11.5h14\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>Line</button>\n        <button type=\"button\" data-shape=\"square\" aria-pressed=\"false\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><rect x=\"1\" y=\"1\" width=\"5\" height=\"5\" fill=\"currentColor\"/><rect x=\"9\" y=\"1.5\" width=\"3.5\" height=\"3.5\" fill=\"currentColor\"/><rect x=\"1.8\" y=\"9\" width=\"3\" height=\"3\" fill=\"currentColor\"/><rect x=\"8\" y=\"8\" width=\"6\" height=\"6\" fill=\"currentColor\"/></svg>Square</button>\n      </div>\n      <label class=\"lbl\" for=\"lpi\"><span>Dot size / ruling</span><output id=\"lpiOut\">72 lines</output></label>\n      <input type=\"range\" id=\"lpi\" min=\"28\" max=\"140\" step=\"1\" value=\"72\">\n      <label class=\"lbl\" for=\"mis\"><span>Misregistration</span><output id=\"misOut\">2.0 px</output></label>\n      <input type=\"range\" id=\"mis\" min=\"0\" max=\"10\" step=\"0.1\" value=\"2\">\n      <label class=\"lbl\" for=\"grainIn\"><span>Ink grain &amp; density drift</span><output id=\"grainOut\">55%</output></label>\n      <input type=\"range\" id=\"grainIn\" min=\"0\" max=\"100\" step=\"1\" value=\"55\">\n    </section>\n\n    <div class=\"foot\">\n      <p>Each drum lays one spot ink as a screen of dots at its own angle. Overlapping inks multiply, as translucent riso ink does on uncoated stock.</p>\n      <p>Ink hex values follow published riso colour references. Everything is generated in this page.</p>\n    </div>\n  </aside>\n\n  <main class=\"wall\" aria-label=\"Proof pinned to the studio wall\">\n    <p class=\"wall-note\">Studio wall · proofs<br><b id=\"proofNo\">Proof № 01</b> — drying</p>\n    <div class=\"wall-ruler\" aria-hidden=\"true\"></div>\n    <div class=\"poster-wrap\" id=\"posterWrap\">\n      <span class=\"tape l\" aria-hidden=\"true\"></span><span class=\"tape r\" aria-hidden=\"true\"></span>\n      <div class=\"poster\" id=\"poster\" role=\"img\" aria-label=\"Risograph proof of the chosen artwork\">\n        <canvas id=\"paperC\"></canvas>\n        <canvas class=\"ink\" id=\"ink0\"></canvas>\n        <canvas class=\"ink\" id=\"ink1\"></canvas>\n        <canvas class=\"ink\" id=\"ink2\"></canvas>\n        <canvas id=\"grain\"></canvas>\n        <canvas id=\"tooth\"></canvas>\n      </div>\n    </div>\n    <div class=\"caption\" id=\"caption\" aria-live=\"polite\">\n      <span class=\"no\" id=\"capNo\">01</span>\n      <div><p class=\"t\" id=\"capTitle\">Sunset — three-colour proof</p><p id=\"capInks\"></p><p id=\"capScreen\"></p></div>\n      <div class=\"cap-actions\">\n        <button type=\"button\" class=\"btn\" id=\"again\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M12 7A5 5 0 113.2 3.8\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/><path d=\"M1.8 1.2l1.4 2.9 3-1\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/></svg>Print again</button>\n        <button type=\"button\" class=\"btn dark\" id=\"download\"><svg viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M7 1v8M3.8 6L7 9.2 10.2 6M1.5 11v2h11v-2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"1.5\"/></svg>Download PNG</button>\n      </div>\n      <span class=\"busy\" id=\"busy\">printing…</span>\n    </div>\n  </main>\n</div>\n<div class=\"toast\" id=\"toast\" role=\"status\" aria-live=\"polite\"></div>\n\n<script>\n(() => {\n'use strict';\nconst $=id=>document.getElementById(id);\nconst TAU=Math.PI*2,D2R=Math.PI/180;\nconst reduceMQ=window.matchMedia('(prefers-reduced-motion: reduce)');\nlet reduced=reduceMQ.matches;\nconst SANS='\"Helvetica Neue\",Helvetica,Arial,\"Nimbus Sans\",\"Liberation Sans\",sans-serif';\nconst HEAVY='\"Arial Black\",\"Helvetica Neue\",Helvetica,\"Nimbus Sans\",\"Liberation Sans\",Arial,sans-serif';\nconst MONO='\"SF Mono\",Menlo,Consolas,\"DejaVu Sans Mono\",\"Liberation Mono\",monospace';\nfunction mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}\nfunction hexRGB(h){const n=parseInt(h.slice(1),16);return [(n>>16)&255,(n>>8)&255,n&255];}\n\n/* ---------------- inks + drums ---------------- */\nconst INKS=[\n  {id:'pink',name:'Fluorescent Pink',hex:'#ff48b0'},\n  {id:'blue',name:'Medium Blue',hex:'#0078bf'},\n  {id:'yellow',name:'Yellow',hex:'#ffe800'},\n  {id:'black',name:'Black',hex:'#1a1a1a'},\n  {id:'teal',name:'Teal',hex:'#00838a'},\n  {id:'orange',name:'Orange',hex:'#ff6c2f'}\n];\nconst inkById=id=>INKS.find(i=>i.id===id)||INKS[0];\nconst drums=[{on:true,ink:'pink',angle:75},{on:true,ink:'blue',angle:15},{on:true,ink:'yellow',angle:45}];\nconst PAPER=[244,239,226];\nconst S={src:'sunset',word:'RISO',shape:'circle',lines:72,mis:2,grain:55,seed:1,proof:1};\nlet mis=[[0,0,0],[0,0,0],[0,0,0]];\n\n/* ---------------- source artwork ---------------- */\nconst SW=300,SH=375;\nconst src=document.createElement('canvas');src.width=SW;src.height=SH;\nconst X=src.getContext('2d',{willReadFrequently:true});\nconst pad=$('pad'),PD=pad.getContext('2d');\nfunction drawSphere(){\n  const g=X.createLinearGradient(0,0,0,SH);g.addColorStop(0,'#10245e');g.addColorStop(.62,'#2f6fd6');g.addColorStop(.63,'#f6d9a8');g.addColorStop(1,'#ffc27a');\n  X.fillStyle=g;X.fillRect(0,0,SW,SH);\n  // stars of light on the backdrop\n  const r=mulberry32(5);X.fillStyle='rgba(255,236,160,.9)';for(let i=0;i<26;i++){const x=r()*SW,y=r()*SH*0.5;X.beginPath();X.arc(x,y,.8+r()*1.8,0,TAU);X.fill();}\n  // floor shadow\n  const sh=X.createRadialGradient(SW*0.58,SH*0.8,4,SW*0.58,SH*0.8,SW*0.42);sh.addColorStop(0,'rgba(60,20,70,.85)');sh.addColorStop(1,'rgba(60,20,70,0)');\n  X.save();X.translate(SW*0.58,SH*0.8);X.scale(1,0.26);X.translate(-SW*0.58,-SH*0.8);X.fillStyle=sh;X.fillRect(0,SH*0.4,SW,SH*0.8);X.restore();\n  // the sphere\n  const cx=SW*0.5,cy=SH*0.5,R=SW*0.34;\n  const s=X.createRadialGradient(cx-R*0.38,cy-R*0.42,R*0.05,cx,cy,R*1.02);\n  s.addColorStop(0,'#fffbe0');s.addColorStop(.18,'#ffe14d');s.addColorStop(.5,'#ff7a3d');s.addColorStop(.82,'#e0306e');s.addColorStop(1,'#3a0d4a');\n  X.fillStyle=s;X.beginPath();X.arc(cx,cy,R,0,TAU);X.fill();\n  // rim light\n  X.strokeStyle='rgba(120,200,255,.55)';X.lineWidth=4;X.beginPath();X.arc(cx,cy,R-2,0.2,1.3);X.stroke();\n  // ring\n  X.strokeStyle='#1c1c3a';X.lineWidth=5;X.beginPath();X.ellipse(cx,cy+6,R*1.45,R*0.3,-0.25,0.1,Math.PI-0.15);X.stroke();\n}\nfunction drawSunset(){\n  const g=X.createLinearGradient(0,0,0,SH*0.6);\n  g.addColorStop(0,'#2a2b8f');g.addColorStop(.35,'#9a3fa8');g.addColorStop(.62,'#ff5f7e');g.addColorStop(.85,'#ffae45');g.addColorStop(1,'#ffe46a');\n  X.fillStyle=g;X.fillRect(0,0,SW,SH);\n  // sun\n  const sx=SW*0.56,sy=SH*0.47,sr=SW*0.2;\n  const sg=X.createRadialGradient(sx,sy-sr*0.3,2,sx,sy,sr);sg.addColorStop(0,'#fffbd0');sg.addColorStop(.6,'#fff06a');sg.addColorStop(1,'#ffc53c');\n  X.fillStyle=sg;X.beginPath();X.arc(sx,sy,sr,0,TAU);X.fill();\n  // thin clouds\n  X.fillStyle='rgba(255,120,150,.8)';\n  [[.1,.3,.5],[.5,.24,.34],[.05,.4,.3],[.62,.38,.36]].forEach(([x,y,w])=>{X.beginPath();X.ellipse(SW*(x+w/2),SH*y,SW*w/2,3.5,0,0,TAU);X.fill();});\n  // ridges: far to near\n  const ridges=[['#8a5bc8',0.5,20,.6],['#4a58c8',0.56,26,1.1],['#1f4fa8',0.62,30,1.7],['#0d2f6e',0.7,24,2.4]];\n  ridges.forEach(([c,base,amp,f],k)=>{\n    const r=mulberry32(40+k);const ph=r()*10;\n    X.fillStyle=c;X.beginPath();X.moveTo(0,SH);\n    for(let x=0;x<=SW;x+=3){\n      const t=x/SW;\n      const y=SH*base-amp*(Math.sin(t*6.3*f+ph)*.55+Math.sin(t*15*f+ph*2)*.25+Math.abs(Math.sin(t*3.1*f+ph*.7))*.8);\n      X.lineTo(x,y);\n    }\n    X.lineTo(SW,SH);X.closePath();X.fill();\n  });\n  // sea\n  const sea=X.createLinearGradient(0,SH*0.74,0,SH);sea.addColorStop(0,'#0a2a66');sea.addColorStop(1,'#051536');\n  X.fillStyle=sea;X.fillRect(0,SH*0.74,SW,SH*0.26);\n  // broken reflection\n  const r=mulberry32(77);\n  for(let i=0;i<22;i++){const y=SH*0.755+i*i*0.21+2;const w=(SW*0.34)*(1-i/26)*(0.6+r()*0.6);X.fillStyle=i%3?'#ffd84a':'#ff7a8a';X.fillRect(sx-w/2+(r()-.5)*10,y,w,1.6+i*0.1);}\n  // birds\n  X.strokeStyle='#161a3a';X.lineWidth=1.6;X.lineCap='round';\n  [[.22,.2,7],[.3,.17,5],[.27,.25,4.5],[.76,.14,6]].forEach(([x,y,s])=>{X.beginPath();X.moveTo(SW*x-s,SH*y);X.quadraticCurveTo(SW*x-s/2,SH*y-s*.6,SW*x,SH*y);X.quadraticCurveTo(SW*x+s/2,SH*y-s*.6,SW*x+s,SH*y);X.stroke();});\n}\nfunction drawWord(){\n  X.fillStyle='#fff6c9';X.fillRect(0,0,SW,SH);\n  // backdrop disc + stripes\n  X.fillStyle='#8ecbff';X.beginPath();X.arc(SW*0.62,SH*0.36,SW*0.42,0,TAU);X.fill();\n  X.fillStyle='#ffd23f';for(let i=0;i<9;i++)X.fillRect(0,SH*0.72+i*12,SW,5);\n  const w=(S.word||' ').toUpperCase();\n  X.save();X.translate(SW/2,SH*0.54);X.rotate(-0.12);\n  let fs=180;X.font='900 '+fs+'px '+HEAVY;let m=X.measureText(w).width;\n  fs=Math.min(200,fs*(SW*0.9)/Math.max(1,m));X.font='900 '+fs+'px '+HEAVY;\n  X.textAlign='center';X.textBaseline='middle';\n  // offset shadow in deep blue\n  X.fillStyle='#10307a';X.fillText(w,fs*0.06,fs*0.07);\n  const g=X.createLinearGradient(0,-fs*0.5,0,fs*0.5);g.addColorStop(0,'#ff3fa4');g.addColorStop(.55,'#ff7a3a');g.addColorStop(1,'#ffd23f');\n  X.fillStyle=g;X.fillText(w,0,0);\n  X.lineWidth=Math.max(1.5,fs*0.018);X.strokeStyle='#1a1a1a';X.strokeText(w,0,0);\n  X.restore();\n}\nfunction drawFace(){\n  X.fillStyle='#ffd84a';X.fillRect(0,0,SW,SH*0.55);\n  X.fillStyle='#4aa3f0';X.fillRect(0,SH*0.55,SW,SH*0.45);\n  X.fillStyle='#ff6fae';X.beginPath();X.arc(SW*0.84,SH*0.14,26,0,TAU);X.fill();\n  // neck + shoulders\n  X.fillStyle='#1c3f96';X.beginPath();X.moveTo(SW*0.12,SH);X.quadraticCurveTo(SW*0.5,SH*0.68,SW*0.88,SH);X.fill();\n  X.fillStyle='#ff9b6a';X.fillRect(SW*0.42,SH*0.62,SW*0.16,SH*0.12);\n  // head\n  const cx=SW*0.5,cy=SH*0.44,R=SW*0.3;\n  X.fillStyle='#ff5fa2';X.beginPath();X.arc(cx,cy,R,0,TAU);X.fill();\n  // hair: black half disc + fringe block\n  X.fillStyle='#161616';X.beginPath();X.arc(cx,cy-R*0.12,R*1.04,Math.PI*1.02,Math.PI*1.98);X.fill();\n  X.fillRect(cx+R*0.05,cy-R*0.62,R*0.9,R*0.36);\n  // eyes: white discs with pupils, one a wink bar\n  X.fillStyle='#fffdf4';X.beginPath();X.arc(cx-R*0.38,cy+R*0.02,R*0.2,0,TAU);X.fill();\n  X.fillStyle='#161616';X.beginPath();X.arc(cx-R*0.34,cy+R*0.05,R*0.09,0,TAU);X.fill();\n  X.fillStyle='#161616';X.fillRect(cx+R*0.2,cy,R*0.34,R*0.08);\n  // nose triangle\n  X.fillStyle='#2a63d6';X.beginPath();X.moveTo(cx+R*0.02,cy+R*0.02);X.lineTo(cx-R*0.14,cy+R*0.42);X.lineTo(cx+R*0.14,cy+R*0.42);X.closePath();X.fill();\n  // cheeks\n  X.fillStyle='#ffb14a';X.beginPath();X.arc(cx-R*0.56,cy+R*0.42,R*0.14,0,TAU);X.fill();X.beginPath();X.arc(cx+R*0.56,cy+R*0.42,R*0.14,0,TAU);X.fill();\n  // mouth\n  X.fillStyle='#d91f3c';X.beginPath();X.moveTo(cx-R*0.3,cy+R*0.6);X.lineTo(cx+R*0.3,cy+R*0.6);X.arc(cx,cy+R*0.6,R*0.3,0,Math.PI);X.fill();\n  // earring\n  X.strokeStyle='#161616';X.lineWidth=4;X.beginPath();X.arc(cx+R*1.0,cy+R*0.5,R*0.12,0,TAU);X.stroke();\n}\nfunction drawDoodle(){\n  X.fillStyle='#fbfaf6';X.fillRect(0,0,SW,SH);\n  X.drawImage(pad,0,0,SW,SH);\n}\nfunction drawSource(){\n  X.setTransform(1,0,0,1,0,0);X.globalAlpha=1;X.globalCompositeOperation='source-over';\n  ({sphere:drawSphere,sunset:drawSunset,word:drawWord,face:drawFace,doodle:drawDoodle})[S.src]();\n  const t=$('thumb').getContext('2d');t.drawImage(src,0,0,192,240);\n}\nfunction seedPad(){\n  PD.fillStyle='#fbfaf6';PD.fillRect(0,0,480,600);\n  PD.lineCap='round';PD.lineJoin='round';\n  const stroke=(c,w,pts)=>{PD.strokeStyle=c;PD.lineWidth=w;PD.beginPath();pts.forEach((p,i)=>i?PD.lineTo(p[0],p[1]):PD.moveTo(p[0],p[1]));PD.stroke();};\n  // a sun with rays, a hill line, a small house and a wobbly star\n  PD.fillStyle='#ffd400';PD.beginPath();PD.arc(330,150,62,0,TAU);PD.fill();\n  for(let i=0;i<12;i++){const a=i/12*TAU;stroke('#ff3fa4',9,[[330+Math.cos(a)*82,150+Math.sin(a)*82],[330+Math.cos(a)*118,150+Math.sin(a)*118]]);}\n  const hill=[];for(let x=-10;x<=490;x+=20)hill.push([x,420-Math.sin(x/70)*38-x*0.08]);stroke('#1a6fd0',16,hill);\n  PD.fillStyle='#1a6fd0';PD.beginPath();PD.moveTo(-10,600);hill.forEach(p=>PD.lineTo(p[0],p[1]+10));PD.lineTo(490,600);PD.fill();\n  stroke('#141414',8,[[90,340],[90,250],[150,200],[210,250],[210,340],[90,340]]);\n  PD.fillStyle='#ff3fa4';PD.fillRect(130,285,34,55);\n  const star=[];for(let i=0;i<=10;i++){const a=-Math.PI/2+i*Math.PI/5,r=i%2?16:38;star.push([110+Math.cos(a)*r,105+Math.sin(a)*r]);}stroke('#141414',6,star);\n  stroke('#ff3fa4',7,[[280,520],[300,500],[320,520],[340,500],[360,520],[380,500],[400,520]]);\n}\n\n/* ---------------- separation: bounded least squares in density space ---------------- */\nlet covMaps=[new Float32Array(SW*SH),new Float32Array(SW*SH),new Float32Array(SW*SH)];\nfunction separate(){\n  const d=X.getImageData(0,0,SW,SH).data;\n  const Dm=drums.map(dr=>{const c=hexRGB(inkById(dr.ink).hex);return c.map(v=>-Math.log10(Math.max(0.03,v/255)));});\n  const n=3,lam=0.015,it=7;\n  const nn=Dm.map(v=>v[0]*v[0]+v[1]*v[1]+v[2]*v[2]+lam);\n  const T=[0,0,0],c=[0,0,0];\n  for(let p=0,q=0;q<SW*SH;p+=4,q++){\n    for(let k=0;k<3;k++)T[k]=-Math.log10(Math.min(1,Math.max(0.03,(d[p+k]/255)/(PAPER[k]/255))));\n    c[0]=c[1]=c[2]=0;\n    for(let s=0;s<it;s++){\n      for(let i=0;i<n;i++){\n        let num=0;\n        for(let k=0;k<3;k++){let r=T[k];for(let j=0;j<n;j++)if(j!==i)r-=c[j]*Dm[j][k];num+=r*Dm[i][k];}\n        let v=num/nn[i];c[i]=v<0?0:v>1?1:v;\n      }\n    }\n    covMaps[0][q]=c[0];covMaps[1][q]=c[1];covMaps[2][q]=c[2];\n  }\n  drawPlates();\n}\nfunction sampleCov(m,u,v){ // u,v in 0..1, bilinear\n  const x=u*(SW-1),y=v*(SH-1);\n  if(x<0||y<0||x>SW-1||y>SH-1)return 0;\n  const x0=x|0,y0=y|0,x1=Math.min(SW-1,x0+1),y1=Math.min(SH-1,y0+1),fx=x-x0,fy=y-y0;\n  const a=m[y0*SW+x0],b=m[y0*SW+x1],c=m[y1*SW+x0],d=m[y1*SW+x1];\n  return (a*(1-fx)+b*fx)*(1-fy)+(c*(1-fx)+d*fx)*fy;\n}\n\n/* ---------------- poster geometry ---------------- */\nconst poster=$('poster'),paperC=$('paperC'),grainC=$('grain'),toothC=$('tooth');\nconst inkC=[$('ink0'),$('ink1'),$('ink2')];\nlet PW=500,PH=672,DPR=1,IX=0,IY=0,IW=0,IH=0;\nfunction sizePoster(){\n  const wall=document.querySelector('.wall');\n  const mobile=window.innerWidth<=900;\n  const availW=mobile?Math.min(wall.clientWidth-40,560):wall.clientWidth-150;\n  const availH=mobile?9999:wall.clientHeight-196;\n  PW=Math.floor(Math.max(240,Math.min(availW,availH/1.345,640)));\n  PH=Math.round(PW*1.345);\n  DPR=Math.min(2,window.devicePixelRatio||1);\n  poster.style.width=PW+'px';poster.style.height=PH+'px';\n  document.querySelector('.caption').style.maxWidth=PW+'px';\n  for(const c of [paperC,grainC,toothC,...inkC]){c.width=Math.round(PW*DPR);c.height=Math.round(PH*DPR);}\n  const m=PW*0.07;IX=m;IY=m;IW=PW-2*m;IH=IW*1.25;\n}\nfunction paintPaper(){\n  const g=paperC.getContext('2d');g.setTransform(DPR,0,0,DPR,0,0);\n  const r=mulberry32(900+S.seed);\n  g.fillStyle='#f4efe2';g.fillRect(0,0,PW,PH);\n  for(let i=0;i<40;i++){const x=r()*PW,y=r()*PH,rad=20+r()*80;const gr=g.createRadialGradient(x,y,0,x,y,rad);gr.addColorStop(0,r()<.5?'rgba(230,220,196,.35)':'rgba(255,253,246,.4)');gr.addColorStop(1,'rgba(255,255,255,0)');g.fillStyle=gr;g.fillRect(x-rad,y-rad,rad*2,rad*2);}\n  const n=Math.round(PW*PH/60);\n  for(let i=0;i<n;i++){g.fillStyle=r()<.55?'rgba(120,100,70,.07)':'rgba(255,255,255,.35)';g.fillRect(r()*PW,r()*PH,.7,.7);}\n  g.lineCap='round';\n  for(let i=0;i<PW*0.9;i++){const x=r()*PW,y=r()*PH,a=r()*Math.PI,l=2+r()*7;g.strokeStyle='rgba(140,120,90,'+(0.05+r()*0.07)+')';g.lineWidth=.35;g.beginPath();g.moveTo(x,y);g.lineTo(x+Math.cos(a)*l,y+Math.sin(a)*l);g.stroke();}\n  // grain overlay (multiply) + paper tooth (screen): paper texture that shows through the ink\n  const gg=grainC.getContext('2d');gg.setTransform(DPR,0,0,DPR,0,0);gg.clearRect(0,0,PW,PH);\n  const m=Math.round(PW*PH/22);\n  for(let i=0;i<m;i++){gg.fillStyle='rgba(90,75,55,'+(0.03+r()*0.09)+')';gg.fillRect(r()*PW,r()*PH,.8,.8);}\n  const tg=toothC.getContext('2d');tg.setTransform(DPR,0,0,DPR,0,0);tg.clearRect(0,0,PW,PH);\n  const k=Math.round(PW*PH/40);\n  for(let i=0;i<k;i++){tg.fillStyle='rgba(255,252,240,'+(0.12+r()*0.3)+')';const s=.6+r()*.9;tg.fillRect(r()*PW,r()*PH,s,s);}\n}\n\n/* ---------------- halftone rendering, one drum at a time ---------------- */\nfunction keyDrum(){ // the darkest ink carries the colophon\n  let best=0,bl=1e9;drums.forEach((d,i)=>{const c=hexRGB(inkById(d.ink).hex);const l=c[0]*.3+c[1]*.59+c[2]*.11;if(l<bl){bl=l;best=i;}});return best;\n}\nfunction renderInk(i){\n  const cv=inkC[i],g=cv.getContext('2d');\n  g.setTransform(DPR,0,0,DPR,0,0);g.globalCompositeOperation='source-over';g.globalAlpha=1;g.clearRect(0,0,PW,PH);\n  const dr=drums[i],ink=inkById(dr.ink).hex,map=covMaps[i];\n  const s=IW/S.lines,th=dr.angle*D2R,cs=Math.cos(th),sn=Math.sin(th);\n  const cx=IX+IW/2,cy=IY+IH/2,Rn=Math.ceil(Math.hypot(IW,IH)/2/s)+1;\n  g.fillStyle=ink;\n  g.save();g.beginPath();g.rect(IX,IY,IW,IH);g.clip();\n  g.translate(cx,cy);g.rotate(th);\n  g.beginPath();\n  const toU=(lx,ly)=>{const x=cx+lx*cs-ly*sn,y=cy+lx*sn+ly*cs;return [(x-IX)/IW,(y-IY)/IH];};\n  const gain=1.04;\n  if(S.shape==='line'){\n    for(let v=-Rn;v<Rn;v++){\n      const ly=(v+0.5)*s;const top=[],bot=[];\n      for(let u=-Rn;u<=Rn;u++){\n        const lx=u*s;const [a,b]=toU(lx,ly);\n        let c=(a<-0.02||a>1.02||b<-0.02||b>1.02)?0:sampleCov(map,Math.min(1,Math.max(0,a)),Math.min(1,Math.max(0,b)));\n        const t=Math.min(s,s*c*gain);top.push(lx,ly-t/2);bot.push(lx,ly+t/2);\n      }\n      g.moveTo(top[0],top[1]);for(let k=2;k<top.length;k+=2)g.lineTo(top[k],top[k+1]);\n      for(let k=bot.length-2;k>=0;k-=2)g.lineTo(bot[k],bot[k+1]);g.closePath();\n    }\n  }else{\n    for(let v=-Rn;v<Rn;v++){\n      const ly=(v+0.5)*s;\n      for(let u=-Rn;u<Rn;u++){\n        const lx=(u+0.5)*s;const [a,b]=toU(lx,ly);\n        if(a<-0.01||a>1.01||b<-0.01||b>1.01)continue;\n        const c=sampleCov(map,Math.min(1,Math.max(0,a)),Math.min(1,Math.max(0,b)))*gain;\n        if(c<0.018)continue;\n        if(S.shape==='square'){const side=s*Math.min(1.02,Math.sqrt(c));g.rect(lx-side/2,ly-side/2,side,side);}\n        else{\n          const r=c<0.785?s*Math.sqrt(c/Math.PI):s*(0.5+(Math.min(1,c)-0.785)/0.215*0.22);\n          g.moveTo(lx+r,ly);g.arc(lx,ly,r,0,TAU);\n        }\n      }\n    }\n  }\n  g.fill();\n  g.restore();\n  // registration marks, colour bar and (for the key drum) the colophon: solid ink, outside the image\n  drawFurniture(g,i,ink);\n  // ink texture: density drift + starvation speckle, knocked out of the layer\n  inkTexture(g,i);\n}\nfunction drawFurniture(g,i,ink){\n  g.save();g.strokeStyle=ink;g.fillStyle=ink;g.lineWidth=Math.max(.8,PW*0.0018);\n  const reg=(x,y)=>{const r=PW*0.016;g.beginPath();g.arc(x,y,r,0,TAU);g.moveTo(x-r*1.7,y);g.lineTo(x+r*1.7,y);g.moveTo(x,y-r*1.7);g.lineTo(x,y+r*1.7);g.stroke();};\n  reg(IX*0.5,IY*0.5);reg(PW-IX*0.5,IY*0.5);reg(IX*0.5,IY+IH+IX*0.5);reg(PW-IX*0.5,IY+IH+IX*0.5);\n  // crop ticks\n  g.beginPath();[[IX,IY],[IX+IW,IY],[IX,IY+IH],[IX+IW,IY+IH]].forEach(([x,y])=>{g.moveTo(x,y-PW*0.012);g.lineTo(x,y-PW*0.03);g.moveTo(x,y+PW*0.012);g.lineTo(x,y+PW*0.03);});g.stroke();\n  // colour bar: own patch solid, own 50% tint, and the shared overprint patch\n  const bs=PW*0.034,by=IY+IH+PW*0.062,bx=PW-IX-bs*5.4;\n  g.fillRect(bx+i*bs*1.1,by,bs,bs);\n  const tint=bx+i*bs*1.1,ty=by+bs*1.12;\n  for(let yy=0;yy<4;yy++)for(let xx=0;xx<4;xx++){g.beginPath();g.arc(tint+bs*(xx+0.5)/4,ty+bs*(yy+0.5)/4*0.9,bs/8*0.8,0,TAU);g.fill();}\n  g.fillRect(bx+3.3*bs*1.1+bs*0.2,by,bs*1.4,bs*2.05);\n  if(i===keyDrum()){\n    g.textBaseline='alphabetic';\n    g.font='900 '+(PW*0.058)+'px '+HEAVY;g.fillText('RISO LAB',IX,IY+IH+PW*0.1);\n    g.font=(PW*0.019)+'px '+MONO;\n    const on=drums.filter(d=>d.on).length;\n    const title=({sphere:'SPHERE',sunset:'SUNSET',word:'“'+(S.word||'').toUpperCase()+'”',face:'FACE',doodle:'DOODLE'})[S.src];\n    g.fillText('PROOF № '+String(S.proof).padStart(2,'0')+' · '+title+' · '+on+'-COLOUR',IX,IY+IH+PW*0.14);\n    g.fillText(drums.map(d=>d.angle+'°').join(' / ')+' · '+S.lines+' LINES · '+S.shape.toUpperCase(),IX,IY+IH+PW*0.168);\n  }\n  g.restore();\n}\nfunction inkTexture(g,i){\n  const r=mulberry32(S.seed*131+i*977+7);\n  const amt=S.grain/100;\n  if(amt<=0)return;\n  g.save();g.globalCompositeOperation='destination-out';\n  // low-frequency density drift (uneven ink on the drum)\n  const lw=24,lh=32;const low=document.createElement('canvas');low.width=lw;low.height=lh;const L=low.getContext('2d');\n  const id=L.createImageData(lw,lh);\n  for(let k=0;k<lw*lh;k++){const v=Math.pow(r(),1.6);id.data[k*4+3]=Math.round(v*255*0.55*amt);}\n  L.putImageData(id,0,0);g.imageSmoothingEnabled=true;g.drawImage(low,0,0,PW,PH);\n  // starvation toward one edge of the sheet\n  const side=r()<.5;const gr=g.createLinearGradient(side?0:PW,0,side?PW:0,0);gr.addColorStop(0,'rgba(0,0,0,'+(0.22*amt)+')');gr.addColorStop(.5,'rgba(0,0,0,0)');g.fillStyle=gr;g.fillRect(0,0,PW,PH);\n  // speckle where ink failed to transfer\n  const n=Math.round(PW*PH/18*amt);\n  for(let k=0;k<n;k++){g.fillStyle='rgba(0,0,0,'+(0.35+r()*0.65)+')';const sz=.5+r()*1.3;g.fillRect(r()*PW,r()*PH,sz,sz);}\n  // a few drag streaks from the drum\n  for(let k=0;k<Math.round(4*amt);k++){g.fillStyle='rgba(0,0,0,'+(0.12+r()*0.18)+')';g.fillRect(r()*PW,0,.8+r()*2,PH);}\n  g.restore();\n}\nfunction rollMisregistration(){\n  const r=mulberry32(S.seed*7+3);\n  mis=drums.map(()=>[(r()*2-1),(r()*2-1),(r()*2-1)]);\n}\nfunction applyMisregistration(){\n  inkC.forEach((c,i)=>{const m=mis[i];const a=S.mis;c.style.transform='translate('+(m[0]*a).toFixed(2)+'px,'+(m[1]*a).toFixed(2)+'px) rotate('+(m[2]*a*0.045).toFixed(3)+'deg)';});\n  $('misOut').textContent=S.mis.toFixed(1)+' px';\n}\nfunction applyToggles(){inkC.forEach((c,i)=>c.classList.toggle('off',!drums[i].on));}\n\n/* ---------------- plates (separation previews) ---------------- */\nconst plateCtx=[];\nfunction drawPlates(){\n  plateCtx.forEach((g,i)=>{\n    if(!g)return;\n    const w=88,h=110,img=g.createImageData(w,h);const rgb=hexRGB(inkById(drums[i].ink).hex);\n    for(let y=0;y<h;y++)for(let x=0;x<w;x++){\n      const c=sampleCov(covMaps[i],x/(w-1),y/(h-1));const p=(y*w+x)*4;\n      img.data[p]=255-(255-rgb[0])*c;img.data[p+1]=255-(255-rgb[1])*c;img.data[p+2]=255-(255-rgb[2])*c;img.data[p+3]=255;\n    }\n    g.putImageData(img,0,0);\n  });\n}\n\n/* ---------------- drum UI (built at runtime) ---------------- */\nconst drumHost=$('drums');\nfunction buildDrums(){\n  drums.forEach((d,i)=>{\n    const row=document.createElement('div');row.className='drum-row';\n    const L=String.fromCharCode(65+i);\n    row.innerHTML=\n      '<button type=\"button\" class=\"drum\" aria-pressed=\"'+d.on+'\" aria-label=\"Drum '+L+' — toggle this ink layer\">'+\n        '<span class=\"slot\"><span class=\"cyl\"></span></span>'+\n        '<span class=\"state\"><span class=\"led\"></span><span>Drum '+L+'</span></span></button>'+\n      '<div class=\"drum-ctl\"><p class=\"ink-name\"><span class=\"nm\"></span><output class=\"ang\"></output></p>'+\n        '<div class=\"inks\" role=\"radiogroup\" aria-label=\"Ink for drum '+L+'\"></div>'+\n        '<input class=\"angle\" type=\"range\" min=\"0\" max=\"90\" step=\"1\" aria-label=\"Screen angle for drum '+L+'\" value=\"'+d.angle+'\"></div>'+\n      '<canvas class=\"plate\" width=\"88\" height=\"110\" role=\"img\" aria-label=\"Separation plate for drum '+L+'\"></canvas>';\n    const inks=row.querySelector('.inks');\n    INKS.forEach(ink=>{\n      const lab=document.createElement('label');lab.title=ink.name;\n      const inp=document.createElement('input');inp.type='radio';inp.name='ink'+i;inp.value=ink.id;inp.checked=ink.id===d.ink;inp.setAttribute('aria-label',ink.name);\n      const sw=document.createElement('span');sw.className='sw';sw.style.background=ink.hex;\n      lab.append(inp,sw);inks.append(lab);\n      inp.addEventListener('change',()=>{if(inp.checked){d.ink=ink.id;syncDrum(i);schedule('sep');}});\n    });\n    const btn=row.querySelector('.drum');\n    btn.addEventListener('click',()=>{\n      d.on=!d.on;btn.setAttribute('aria-pressed',String(d.on));\n      btn.classList.remove('spin');void btn.offsetWidth;btn.classList.add('spin');\n      applyToggles();\n      if(d.on&&!reduced){const c=inkC[i];c.classList.remove('wipe');c.style.animationDelay='0s';void c.offsetWidth;c.classList.add('wipe');}\n      if(!drums.some(x=>x.on))toast('All drums are out — the sheet runs blank');\n      schedule('key');updateCaption();\n    });\n    const ang=row.querySelector('.angle');\n    ang.addEventListener('input',()=>{d.angle=+ang.value;syncDrum(i);schedule('ink'+i);});\n    plateCtx[i]=row.querySelector('.plate').getContext('2d');\n    drumHost.append(row);\n    row._btn=btn;row._ang=ang;\n    syncDrum(i);\n  });\n}\nfunction syncDrum(i){\n  const row=drumHost.children[i];if(!row)return;\n  const ink=inkById(drums[i].ink);\n  row.querySelector('.cyl').style.setProperty('--c',ink.hex);\n  row.querySelector('.nm').textContent=ink.name;\n  row.querySelector('.ang').textContent=drums[i].angle+'°';\n  updateCaption();\n}\n\n/* ---------------- scheduling ---------------- */\nlet pending={sep:false,all:false,ink:[false,false,false],key:false,paper:false},raf=0;\nfunction schedule(what){\n  if(what==='sep'){pending.sep=true;pending.all=true;}\n  else if(what==='all')pending.all=true;\n  else if(what==='paper'){pending.paper=true;pending.all=true;}\n  else if(what==='key')pending.key=true;\n  else if(what.startsWith('ink'))pending.ink[+what.slice(3)]=true;\n  $('busy').classList.add('on');\n  if(!raf)raf=requestAnimationFrame(()=>requestAnimationFrame(run));\n}\nlet wipeNext=false;\nfunction run(){\n  raf=0;\n  const p=pending;pending={sep:false,all:false,ink:[false,false,false],key:false,paper:false};\n  if(p.sep){drawSource();separate();}\n  if(p.paper)paintPaper();\n  if(p.all){for(let i=0;i<3;i++)renderInk(i);}\n  else{\n    const k=keyDrum();\n    for(let i=0;i<3;i++)if(p.ink[i]||(p.key&&i===k))renderInk(i);\n  }\n  applyToggles();applyMisregistration();\n  if(wipeNext&&!reduced){\n    wipeNext=false;\n    inkC.forEach((c,i)=>{c.classList.remove('wipe');void c.offsetWidth;c.style.animationDelay=(i*0.2)+'s';c.classList.add('wipe');});\n  }\n  updateCaption();\n  $('busy').classList.remove('on');\n}\n\n/* ---------------- caption ---------------- */\nfunction updateCaption(){\n  const on=drums.map((d,i)=>({d,i})).filter(x=>x.d.on);\n  const names={sphere:'Sphere',sunset:'Sunset',word:'“'+(S.word||'').toUpperCase()+'”',face:'Geometric face',doodle:'Your doodle'};\n  const count=['blank','one-colour','two-colour','three-colour'][on.length];\n  $('capNo').textContent=String(S.proof).padStart(2,'0');\n  $('proofNo').textContent='Proof № '+String(S.proof).padStart(2,'0');\n  $('capTitle').textContent=names[S.src]+' — '+count+' proof';\n  $('capInks').textContent=on.length?on.map(x=>inkById(x.d.ink).name+' '+x.d.angle+'°').join(' · '):'No drums loaded';\n  $('capScreen').textContent=S.lines+' lines across · '+(IW/S.lines).toFixed(1)+' px '+S.shape+' dots · misregistration '+S.mis.toFixed(1)+' px';\n  $('lpiOut').textContent=S.lines+' lines · '+(IW/S.lines).toFixed(1)+' px';\n}\n\n/* ---------------- controls ---------------- */\nconst notes={\n  sphere:'<b>Sphere.</b> A lit ball over a dusk floor — a smooth tonal ramp that shows off the dots.',\n  sunset:'<b>Sunset.</b> Layered ridges, a low sun and its broken reflection. The original, before separation.',\n  word:'<b>Word.</b> Type up to ten letters; they are set huge, tilted and shadowed.',\n  face:'<b>Face.</b> A flat geometric portrait: discs, a triangle nose, a wink.',\n  doodle:'<b>Doodle.</b> Draw on the pad below — the proof re-screens as you go.'\n};\ndocument.querySelectorAll('.src').forEach(b=>b.addEventListener('click',()=>{\n  S.src=b.dataset.src;\n  document.querySelectorAll('.src').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));\n  $('srcNote').innerHTML=notes[S.src];\n  $('wordBox').hidden=S.src!=='word';$('padBox').hidden=S.src!=='doodle';\n  S.proof++;wipeNext=true;schedule('sep');\n  if(S.src==='word')setTimeout(()=>{try{$('word').focus({preventScroll:true});}catch(e){}},50);\n}));\nconst wordIn=$('word');\nwordIn.addEventListener('input',()=>{\n  S.word=wordIn.value.replace(/\\s+/g,' ').slice(0,10);$('wordLen').textContent=S.word.length+'/10';schedule('sep');\n});\ndocument.querySelectorAll('[data-shape]').forEach(b=>b.addEventListener('click',()=>{\n  S.shape=b.dataset.shape;document.querySelectorAll('[data-shape]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));schedule('all');\n}));\n$('lpi').addEventListener('input',e=>{S.lines=+e.target.value;updateCaption();schedule('all');});\n$('mis').addEventListener('input',e=>{S.mis=+e.target.value;applyMisregistration();updateCaption();});\n$('grainIn').addEventListener('input',e=>{S.grain=+e.target.value;$('grainOut').textContent=S.grain+'%';schedule('all');});\n$('again').addEventListener('click',()=>{S.seed++;S.proof++;rollMisregistration();wipeNext=true;schedule('paper');toast('Proof № '+String(S.proof).padStart(2,'0')+' pulled — each pass lands a little differently');});\n\n/* doodle pad */\nlet brush='#ff3fa4',drawing=false,last=null,padTimer=0;\ndocument.querySelectorAll('.brush').forEach(b=>b.addEventListener('click',()=>{brush=b.dataset.c;document.querySelectorAll('.brush').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}));\nfunction padXY(e){const r=pad.getBoundingClientRect();return [(e.clientX-r.left)/r.width*480,(e.clientY-r.top)/r.height*600];}\npad.addEventListener('pointerdown',e=>{drawing=true;last=padXY(e);try{pad.setPointerCapture(e.pointerId);}catch(err){}dot(last);});\npad.addEventListener('pointermove',e=>{if(!drawing)return;const p=padXY(e);PD.strokeStyle=brush;PD.lineWidth=13;PD.lineCap='round';PD.beginPath();PD.moveTo(last[0],last[1]);PD.lineTo(p[0],p[1]);PD.stroke();last=p;padChanged();});\nconst endPad=()=>{drawing=false;};\npad.addEventListener('pointerup',endPad);pad.addEventListener('pointercancel',endPad);\nfunction dot(p){PD.fillStyle=brush;PD.beginPath();PD.arc(p[0],p[1],6.5,0,TAU);PD.fill();padChanged();}\nfunction padChanged(){if(S.src!=='doodle')return;clearTimeout(padTimer);padTimer=setTimeout(()=>schedule('sep'),90);}\n$('padClear').addEventListener('click',()=>{PD.fillStyle='#fbfaf6';PD.fillRect(0,0,480,600);padChanged();});\n\n/* download: flatten paper + inks (multiply, with the same misregistration) + paper texture */\n$('download').addEventListener('click',()=>{\n  try{\n    const out=document.createElement('canvas');const sc=2;out.width=Math.round(PW*sc);out.height=Math.round(PH*sc);\n    const o=out.getContext('2d');\n    o.drawImage(paperC,0,0,out.width,out.height);\n    o.globalCompositeOperation='multiply';\n    inkC.forEach((c,i)=>{\n      if(!drums[i].on)return;const m=mis[i],a=S.mis;\n      o.save();o.translate(out.width/2+m[0]*a*sc,out.height/2+m[1]*a*sc);o.rotate(m[2]*a*0.045*D2R);o.translate(-out.width/2,-out.height/2);\n      o.drawImage(c,0,0,out.width,out.height);o.restore();\n    });\n    o.globalAlpha=.8;o.drawImage(grainC,0,0,out.width,out.height);\n    o.globalCompositeOperation='screen';o.globalAlpha=.9;o.drawImage(toothC,0,0,out.width,out.height);\n    out.toBlob(b=>{\n      if(!b){toast('Export refused by this browser');return;}\n      const u=makeObj.call(URL,b),a=document.createElement('a');a.href=u;a.download='riso-lab-proof-'+String(S.proof).padStart(2,'0')+'.png';\n      document.body.appendChild(a);a.click();a.remove();setTimeout(()=>dropObj.call(URL,u),5000);\n      toast('Saved riso-lab-proof-'+String(S.proof).padStart(2,'0')+'.png');\n    },'image/png');\n  }catch(err){toast('Export refused by this browser');}\n});\nconst makeObj=URL.createObjectURL,dropObj=URL.revokeObjectURL;\n\nlet toastT=0;\nfunction toast(t){const el=$('toast');el.textContent=t;el.classList.add('show');clearTimeout(toastT);toastT=setTimeout(()=>el.classList.remove('show'),2600);}\n\n/* ---------------- boot ---------------- */\nfunction relayout(){sizePoster();paintPaper();schedule('all');}\nseedPad();\nbuildDrums();\ndocument.querySelectorAll('.src').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.src===S.src)));\ndocument.querySelectorAll('[data-shape]').forEach(x=>x.setAttribute('aria-pressed',String(x.dataset.shape===S.shape)));\n$('srcNote').innerHTML=notes[S.src];$('wordBox').hidden=S.src!=='word';$('padBox').hidden=S.src!=='doodle';\nrollMisregistration();\nsizePoster();\ndrawSource();separate();paintPaper();\nfor(let i=0;i<3;i++)renderInk(i);\napplyToggles();applyMisregistration();updateCaption();\nlet rz=0,lastW=window.innerWidth;\nwindow.addEventListener('resize',()=>{clearTimeout(rz);rz=setTimeout(()=>{relayout();lastW=window.innerWidth;},120);});\nreduceMQ.addEventListener&&reduceMQ.addEventListener('change',e=>{reduced=e.matches;});\n})();\n</script>\n</body>\n</html>\n";
